import { sql } from "drizzle-orm";
import { timestamp, uuid } from "drizzle-orm/pg-core";
import { DEFAULT_TENANT_ID } from "./_tenant-constants.js";

/** Standard primary key: UUID generated by Postgres (gen_random_uuid via pgcrypto). */
export const idColumn = () => uuid("id").primaryKey().default(sql`gen_random_uuid()`);

/**
 * Standard tenant-scoping column, added to every tenant-owned table.
 *
 * Deliberately `NOT NULL` with a server-side default from day one rather
 * than "nullable now, NOT NULL later": Postgres 11+ backfills a NOT NULL
 * default on an existing table without rewriting/locking it, so there's
 * no zero-downtime benefit to going nullable first - and going nullable
 * first would mean every query written between now and Phase 3 has to
 * remember to handle a null tenant_id, which is exactly the kind of gap
 * a real tenant-isolation bug hides in. Every pre-existing row backfills
 * onto DEFAULT_TENANT_ID; anything inserted before Phase 2's app-layer
 * plumbing lands there too, rather than failing.
 *
 * PHASE 3 (later, once every repository goes through the tenant-scoping
 * helper in @travel/database): this column drops its default so a write
 * that forgets to set tenantId fails loudly instead of silently landing
 * on the default tenant. Search for "PHASE 3" in this repo to find every
 * place that follow-up touches.
 *
 * This helper only builds the column - every call site chains
 * `.references(() => tenants.id, { onDelete: "restrict" })` itself (can't
 * be baked in here without tenants.ts and _helpers.ts importing each
 * other). onDelete is deliberately "restrict", not "cascade": deleting a
 * tenant is a rare, deliberate, audited admin action (see
 * services/admin), never something that should silently cascade-delete
 * every booking/payment/user a foreign key happens to point at.
 */
export const tenantIdColumn = () =>
  uuid("tenant_id")
    .notNull()
    .default(sql.raw(`'${DEFAULT_TENANT_ID}'`));

/** Standard created_at/updated_at pair. updated_at is maintained by application code / triggers. */
export const timestampColumns = {
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
};

/** Soft-delete marker for user-facing entities. Null = active. */
export const softDeleteColumn = {
  deletedAt: timestamp("deleted_at", { withTimezone: true }),
};
